Definition LREL (A Ak : AS) (P : word -> Prop) : Prop :=
  (forall q, ~ P q -> live Ak q = live A q) /\ (forall q, P q -> live A q = None /\ live Ak q <> None) /\
  (forall q k, live A q = Some k -> live Ak q = Some k).

